<script setup lang="ts">
import { ref, computed } from 'vue'
import Icon from './Icon.vue'
import type { AppState } from './types'
const props = defineProps<{ state: AppState; busy: string }>()
const emit = defineEmits<{ action: [method: string, params: Record<string, unknown>, message: string] }>()
const selected = ref(['codex','gemini']), duration = ref(0)
const running = computed(() => props.state.diagnostics?.running)
const labels: Record<string,string> = { reachable: 'HTTP 可达', restricted: '访问受限', method_unsupported: '方法受限', failed: '连接失败', tls_error: '证书失败', interrupted: '中途断开', service_error: '服务错误', closed: '服务关闭连接', cancelled: '已取消' }
const resultSelected = ref(-1)
const progress = computed(() => props.state.diagnostics ? props.state.diagnostics.results.length / props.state.diagnostics.total * 100 : 0)
</script>
<template><div class="workspace-page">
  <section class="panel diagnostic-config"><div class="section-heading"><div><span class="eyebrow muted">CHECK YOUR CONNECTION</span><h3>一次检测，比较两条路径</h3><p>对比原上游与优化中继，不发送模型生成请求。</p></div><span class="badge" :class="{success:running}">{{ running ? '检测进行中' : '按需检测' }}</span></div><fieldset :disabled="!!running || !!busy"><legend class="field-label">选择 AI 服务</legend><div class="provider-options"><label v-for="(provider,key) in state.providers" :key="key" class="provider-option" :class="{selected:selected.includes(String(key))}"><input v-model="selected" type="checkbox" :value="key"><span class="provider-check"><Icon v-if="selected.includes(String(key))" name="check" :size="14"/></span><Icon :name="String(key).includes('gemini') ? 'bolt' : 'terminal'"/><span>{{ provider.name }}</span></label></div><div class="diagnostic-actions"><label for="diagnostic-duration">检测时长<select id="diagnostic-duration" v-model="duration"><option :value="0">快速检测</option><option :value="30">30 秒持续检测</option><option :value="60">60 秒持续检测</option></select></label><button class="btn primary" :disabled="!selected.length" @click="emit('action','diagnostics.start',{ providers:selected, duration },'连接诊断已开始。')"><Icon name="play" :size="17"/>开始检测</button></div></fieldset><button v-if="running" class="btn secondary cancel-test" :disabled="!!busy" @click="emit('action','diagnostics.cancel',{},'已请求取消检测。')"><Icon name="pause" :size="17"/>取消检测</button></section>
  <section class="panel results-panel"><div class="section-heading"><div><h3>检测结果</h3><p>{{ state.diagnostics ? `${state.diagnostics.results.length} / ${state.diagnostics.total} 项结果 · ${running ? '进行中' : '已结束'}` : '完成检测后，结果会显示在这里。' }}</p></div><Icon v-if="running" name="refresh" class="spinning"/></div><div v-if="state.diagnostics" class="progress-track diagnostic-progress"><div :style="{width:`${progress}%`}"></div></div><div v-if="!state.diagnostics?.results.length" class="empty-state"><span class="empty-icon"><Icon name="pulse" :size="29"/></span><strong>{{ running ? '正在检查连接…' : '还没有检测结果' }}</strong><p>{{ running ? 'TLS 握手与 HTTP 响应需要一些时间，请保持应用运行。' : '选择需要检查的服务，开始第一次连接诊断。' }}</p></div><div v-else class="table-scroll"><table><thead><tr><th>服务</th><th>路径</th><th>结果</th><th>首次耗时</th><th>HTTP</th></tr></thead><tbody><tr v-for="(result,index) in state.diagnostics.results" :key="`${state.diagnostics.id}-${index}`" :class="{selected:resultSelected===index}" tabindex="0" @click="resultSelected=index" @keydown.enter="resultSelected=index"><td><strong>{{ state.providers[result.provider]?.name || result.provider }}</strong></td><td><span class="route-badge">{{ result.route==='relay' ? '优化中继' : '原上游' }}</span></td><td><span class="result-status" :class="{bad:['failed','tls_error','interrupted'].includes(result.outcome)}"><i></i>{{ labels[result.outcome] || result.outcome }}</span></td><td class="tabular">{{ result.latency_ms ? `${Math.round(result.latency_ms)} ms` : '—' }}</td><td class="tabular">{{ result.status || '—' }}</td></tr></tbody></table></div><div v-if="resultSelected>=0 && state.diagnostics?.results[resultSelected]" class="result-detail"><Icon name="info" :size="18"/><p>{{ state.diagnostics.results[resultSelected].note }}</p></div></section>
  <div class="notice neutral"><Icon name="shield"/><span>使用原始证书校验，检测不包含登录凭据。HTTP 可达与模型可用是不同的检查；服务拒绝 HEAD 方法时，也会保留实际返回结果。</span></div>
</div></template>
